-- Compact 2GIS sectors and persisted field trips.
create table public.field_sales_trips(id uuid primary key default gen_random_uuid(),zone_id text not null references public.field_sales_zones(id) on update cascade,actor_id uuid references auth.users(id) on delete set null,status text not null default 'active' check(status in ('active','completed','cancelled')),started_at timestamptz not null default now(),completed_at timestamptz,created_at timestamptz not null default now());
create table public.field_sales_trip_stops(id uuid primary key default gen_random_uuid(),trip_id uuid not null references public.field_sales_trips(id) on delete cascade,lead_id uuid not null references public.field_sales_leads(id) on delete cascade,position integer not null check(position>0),state text not null default 'queued' check(state in ('queued','current','completed','skipped')),outcome text check(outcome is null or outcome in ('interested','follow_up','not_available','refused','connected')),feedback text not null default '',opened_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now(),unique(trip_id,position),unique(trip_id,lead_id));
create unique index field_sales_one_active_trip on public.field_sales_trips(actor_id) where status='active';
create index field_sales_trip_stops_trip_idx on public.field_sales_trip_stops(trip_id,position);
alter table public.field_sales_trips enable row level security; alter table public.field_sales_trip_stops enable row level security; revoke all on table public.field_sales_trips from public,anon,authenticated; revoke all on table public.field_sales_trip_stops from public,anon,authenticated;
